/* From Uiverse.io by Subaashbala  - Tags: skeuomorphism, minimalist, switch, click animation */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 0.25em;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: hotpink;
  transition: 0.4s;
  border-radius: 30px;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "O";
  display: grid;
  text-align: center;
  vertical-align: middle;
  place-items: center;
  font-size: 1em;
  font-weight: 900;
  width: 2em;
  aspect-ratio: 1;
  border-radius: 50%;
  bottom: 0.3em;
  left: 0;
  top: 50%;
  transform: translate(0, -50%);
  color: hotpink;
  background-color: pink;
  border: 1px solid rgba(255, 105, 180, 0.507);
  transition: 0.4s;
}

.__UIV_SCOPE__ .switch input:checked + .slider {
  background-color: teal;
}

.__UIV_SCOPE__ .switch input:checked + .slider:before {
  content: "|";
  color: teal;
  background: paleturquoise;
  border: 1px solid rgba(0, 128, 128, 0.514);
  transform: translate(1.75em, -50%) rotateZ(360deg);
}
